def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    my_def = sum(1 for a in my if a == 'D')
    op_def = sum(1 for a in op if a == 'D')

    if n >= 99:
        return 'D'

    if op_def == n:
        return 'D'

    if op_def == 0:
        if my_def == 0:
            if n >= 25:
                return 'D'
            else:
                return 'C'
        else:
            return 'D'

    last_me, last_op = history[-1]

    if last_op == 'D':
        recent_def = sum(1 for a in op[-5:] if a == 'D')
        if recent_def >= 3:
            recent_c = sum(1 for a in op[-6:] if a == 'C')
            if recent_c == 0:
                return 'D'
            my_recent_def = sum(1 for a in my[-3:] if a == 'D')
            if my_recent_def >= 3:
                return 'C'
            return 'D'
        else:
            return 'C'
    else:
        return 'C'
